import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";var i=JSON.parse(`{"title":"Settings and limits","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/configuration.md","filePath":"en/reference/configuration.md","lastUpdated":1794405696000}`),a={name:`en/reference/configuration.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="settings-and-limits" tabindex="-1">Settings and limits <a class="header-anchor" href="#settings-and-limits" aria-label="Permalink to “Settings and limits”">​</a></h1><h2 id="runtime-settings" tabindex="-1">Runtime settings <a class="header-anchor" href="#runtime-settings" aria-label="Permalink to “Runtime settings”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td>AUTH_MODE</td><td><code>passkey</code> to use the new admin console</td></tr><tr><td>AUTH_ORIGIN</td><td>The fixed admin console origin. HTTPS, no trailing slash</td></tr><tr><td>AUTH_SECRET</td><td>A signing secret per environment. At least 32 characters</td></tr><tr><td>ADMIN_TOKEN</td><td>For first superuser registration. At least 32 characters</td></tr><tr><td>JEV_KEYRING / JEV_KEYRING_FILE</td><td>The keystore for encrypting site API keys, or its secret file</td></tr><tr><td>JEV_MODEL</td><td>The model name used for initial setup</td></tr><tr><td>DAILY_REQUEST_BUDGET</td><td>The daily execution limit (UTC) used for initial setup</td></tr><tr><td>MAX_CONCURRENT</td><td>The concurrency used for initial setup</td></tr><tr><td>DEPLOYMENT_TIER</td><td>Set <code>preview</code> for Preview only</td></tr><tr><td>PREVIEW_MODEL_MODE</td><td>Use test values with the Preview <code>stub</code></td></tr><tr><td>PREVIEW_ACCESS_DOMAIN / AUD</td><td>The issuer and the application that Access trusts</td></tr></tbody></table><p>The model and budget are carried into the admin database at first registration. After that, the place to set them is the superuser&#39;s &quot;JevSense management (「JevSense管理」)&quot;. You don&#39;t override the database values by rewriting only environment variables.</p><p>A site-only key needs the runtime secret <code>JEV_KEYRING</code>. Only Node.js can instead read the file given by <code>JEV_KEYRING_FILE</code>. For details, see <a href="./../operations/jev-keys">operating the encryption key</a>.</p><h2 id="main-admin-console-settings" tabindex="-1">Main admin console settings <a class="header-anchor" href="#main-admin-console-settings" aria-label="Permalink to “Main admin console settings”">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th></tr></thead><tbody><tr><td>Site origins</td><td>Up to 10</td></tr><tr><td>Sites</td><td>Up to 100</td></tr><tr><td>Campaigns in the live settings</td><td>Up to 5 per site</td></tr><tr><td>Questions</td><td>Up to 5 per campaign, up to 10 per site in total</td></tr><tr><td>Presented content and each condition</td><td>Up to 400 characters each</td></tr><tr><td>Judgment threshold</td><td>0.5 to 0.99. A visitor must be strictly above</td></tr><tr><td>Display count</td><td>1 to 10</td></tr><tr><td>Priority</td><td>0 to 100</td></tr><tr><td>Valid viewing time</td><td>1000 to 300000 milliseconds</td></tr><tr><td>Valid views required</td><td>1 to 10</td></tr><tr><td>Saved drafts</td><td>Up to 20 per site</td></tr><tr><td>Passkeys</td><td>Up to 10 per user</td></tr></tbody></table><h2 id="input-and-communication-limits" tabindex="-1">Input and communication limits <a class="header-anchor" href="#input-and-communication-limits" aria-label="Permalink to “Input and communication limits”">​</a></h2><p>The request body is limited to 64 KiB. Valid browsing history is up to 50 entries, optional events up to 30 and confirmed states up to 20 items. Even within those limits, the length of page information may reach the body size limit.</p><p>The design uses only permitted names, paths and types, and treats unknown values and invalid probabilities as not being a target.</p><h2 id="expiry" tabindex="-1">Expiry <a class="header-anchor" href="#expiry" aria-label="Permalink to “Expiry”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Expiry and handling</th></tr></thead><tbody><tr><td>Admin session</td><td>30 minutes idle, 12 hours absolute</td></tr><tr><td>Re-authentication for important operations</td><td>Within 5 minutes</td></tr><tr><td>Invitation link</td><td>24 hours, one use</td></tr><tr><td>Superuser recovery link</td><td>5 minutes, one use</td></tr><tr><td>Authentication challenge</td><td>5 minutes, one use</td></tr><tr><td>Real-page check ticket</td><td>5 minutes, one use</td></tr><tr><td>Fetch authority for checking custom code</td><td>30 seconds, one use</td></tr><tr><td>Diagnostic authorization</td><td>Up to 15 minutes</td></tr></tbody></table><h2 id="rough-roles-of-the-apis" tabindex="-1">Rough roles of the APIs <a class="header-anchor" href="#rough-roles-of-the-apis" aria-label="Permalink to “Rough roles of the APIs”">​</a></h2><p>The public SDK uses <code>/v1/sites/:siteId</code>, <code>/v1/decision</code> and so on. Administrator sign-in is <code>/auth/*</code>, and per-site administration is <code>/admin/api/v2/*</code>.</p><p>Don&#39;t distribute admin cookies or admin tokens to the SDK. For the actual schema and concurrency control, see the <a href="https://github.com/manji6/jev-personalization/blob/main/docs/admin-v2-design.md" target="_blank" rel="noreferrer">detailed design</a>.</p><h2 id="jev-connection-and-record-limits" tabindex="-1">Jev connection and record limits <a class="header-anchor" href="#jev-connection-and-record-limits" aria-label="Permalink to “Jev connection and record limits”">​</a></h2><p>A site&#39;s connection mode is one of three: shared, site-only and stopped. A site-only API key is 8 to 4096 printable ASCII characters with no spaces. The encryption keystore uses up to 10 generations of 32 bytes each. Usage records are shown for up to 90 days by UTC day, with the latest 100 entries. API keys and usage records are for site admins and superusers only.</p><p>URL exclusion keys are the per-site <code>excludedQueryKeys</code> (up to 50, each up to 100 characters). A campaign&#39;s <code>minimumHistory</code> is 0 to 10, and the site setting is used if it is unspecified. URL conditions are up to 5 in <code>urlTargeting.conditions</code>. The decision method is <code>decisionMode: model | rules</code>. The new SDK separates the current and entry pages with <code>protocolVersion: 2</code>, and keeps page URLs up to 4,096 characters.</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};